
#STL imports
from pathlib import Path
import logging

#3rd party imports
import pandas as pd
import matplotlib.pyplot as plt

logger = logging.getLogger(__name__)

def df_from_txt(filepath:Path)->pd.DataFrame:
    """Read in the txt file generated by the data logger that is run in parallel
    to TRIOS

    123456789101112131415161718192021222324252627282930313233343536Args:
        filepath: Path object representing the file from which the data will be
            read 

    Returns:
        A pandas Dataframe representing the data.

    Raises:
        ProcessingError if time column is not monotonic increasing

    """
    logger.debug(f'reading df from  {filepath}')
    num_cols = 0
    with open(filepath) as fh:
        fh.readline()
        num_cols = len(fh.readline().split())
    col_names = [f'unknown{n}' for n in range(num_cols)]
    col_names[:6] = ['time', 'encoder', 'torque',
            'marker', 'force', 'gap']

    df = pd.read_csv(filepath,delimiter='\s+|\t',
                    names=col_names, skiprows=1, engine='python', dtype=str)\
        .drop('marker',axis=1)\
        .stack().str.replace(',', '.').astype(float).unstack()\
        .assign(force  =lambda df: df.force * -1.0)\
        .assign(gap    =lambda df: df.gap   * 1e-6)

    df = df.assign(disp   =lambda df: df.gap -df.gap.iloc[0])\
        .set_index('time')\
        .sort_index()

    if not df.index.is_monotonic_increasing:
        raise ValueError('time not monotonic increasing')

    return df



if __name__ == "__main__":

    filepath = Path(r"C:\Users\iwtm663\Documents\trios_automation\test\out\datalogger\test.txt")
    df = df_from_txt(filepath)

    ax = plt.figure().add_subplot()
    df[['gap','force']].plot(ax=ax,subplots=True)

    ax = plt.figure().add_subplot()
    df[['encoder','torque']].plot(ax=ax,subplots=True)

    plt.show()